/*
 * A127714  Triangle, read by rows of (n+1)*(n+2)/2 terms, generated by the
 *          following rule. Start with a single '1' in row n=0; from then on,
 *          obtain row n from row n-1 by inserting zeros in row n-1 at
 *          positions: {(j+1)*n - j*(j-1)/2 | j=0..n} and then take partial
 *          sums.
 * https://oeis.org/A127714
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   not stated
 * Range:     u8 n <= 46, u16 n <= 68, u32 n <= 68, u64 n <= 68, u128 n <= 68,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computes a(n) for OEIS A127714
   Rules: start with row 0 = [1].  
   For each subsequent row n >= 1, insert zeros into the previous
   row at positions {(j+1)*n - j*(j-1)/2 | j = 0 .. n}  
   then take running partial sums to form the new row.
   The sequence a(n) is the triangle read row‑by‑row.
   Complexity: O(n) over all values up to n.  */

#include <stdlib.h>
#include <stddef.h>

seq_t a(idx_t n)
{
    /* Static tables maintained between calls */
    static seq_t *values    = NULL;  /* Flattened triangle values */
    static size_t values_len = 0;    /* Number of stored values   */
    static size_t values_cap = 0;    /* Capacity of values array  */

    static seq_t *prev_row   = NULL; /* The latest complete row */
    static size_t prev_len   = 0;    /* Length of that row        */
    static idx_t  row_index  = 0;    /* Current triangle row n    */

    /* --- first call: initialise with row 0 === [1] --- */
    if (!values)
    {
        prev_len = 1;
        prev_row = (seq_t *)malloc(sizeof(seq_t));
        prev_row[0] = 1;

        values_cap = 1;
        values = (seq_t *)malloc(values_cap * sizeof(seq_t));
        values[0] = 1;
        values_len = 1;
    }

    /* Generate rows until we have at least n+1 terms */
    while (values_len <= (size_t)n)
    {
        idx_t next_row = row_index + 1;                    /* new row number          */
        size_t Lprev   = prev_len;                         /* length of previous row   */
        size_t Lnew    = (size_t)(next_row + 1) * (next_row + 2) / 2; /* new row length */

        /* Pre‑compute zero insertion positions */
        size_t *zero_pos = (size_t *)malloc((next_row + 1) * sizeof(size_t));
        for (idx_t j = 0; j <= next_row; ++j)
            zero_pos[j] = (size_t)(j + 1) * (size_t)next_row
                          - (size_t)j * (j - 1) / 2;

        /* Build raw array with zeros inserted */
        seq_t *new_row = (seq_t *)malloc(Lnew * sizeof(seq_t));
        size_t z_idx   = 0;
        size_t p_idx   = 0;
        for (size_t i = 0; i < Lnew; ++i)
        {
            if (z_idx <= (size_t)next_row && i == zero_pos[z_idx])
            {
                new_row[i] = 0;
                ++z_idx;
            }
            else
            {
                new_row[i] = prev_row[p_idx++];
            }
        }
        free(zero_pos);

        /* Transform to partial sums */
        for (size_t i = 1; i < Lnew; ++i)
            new_row[i] += new_row[i - 1];

        /* Resize the values table if necessary */
        if (values_len + Lnew > values_cap)
        {
            size_t new_cap = values_cap ? values_cap * 2 : 1;
            while (values_len + Lnew > new_cap)
                new_cap *= 2;
            values = (seq_t *)realloc(values, new_cap * sizeof(seq_t));
            values_cap = new_cap;
        }

        /* Append the new row to the linear list of values */
        for (size_t i = 0; i < Lnew; ++i)
            values[values_len + i] = new_row[i];
        values_len += Lnew;

        /* Prepare for next iteration */
        free(prev_row);
        prev_row = new_row;
        prev_len = Lnew;
        row_index = next_row;
    }

    return values[(size_t)n];
}
